INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r06', 'reading', NULL, 5, '{"id":"r06","level":"A1","title":"Un modulo in biblioteca","theme":"forms","sentences":[["Per fare la tessera compilo un modulo alla reception.","To get a card, I complete a form at reception."],["Scrivo nome, cognome, indirizzo e data di nascita.","I write my first name, surname, address and date of birth."],["Mostro un documento d’identità valido.","I show a valid identity document."],["La tessera costa cinque euro ed è pronta subito.","The card costs five euros and is ready immediately."],["La biblioteca chiude alle diciotto.","The library closes at six p.m."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r07', 'reading', NULL, 6, '{"id":"r07","level":"A1","title":"Messaggio a un’amica","theme":"messages","sentences":[["Ciao Marta, sabato sono libera nel pomeriggio.","Hi Marta, I’m free on Saturday afternoon."],["Ti va di visitare il nuovo museo in centro?","Would you like to visit the new museum in the centre?"],["Possiamo incontrarci davanti alla stazione alle due.","We can meet outside the station at two."],["Dopo il museo vorrei prendere un gelato.","After the museum I’d like to have an ice cream."],["Fammi sapere entro venerdì.","Let me know by Friday."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r08', 'reading', NULL, 7, '{"id":"r08","level":"A1","title":"Orari del centro sportivo","theme":"timetable","sentences":[["Il centro sportivo apre dal lunedì al sabato.","The sports centre opens from Monday to Saturday."],["La piscina è disponibile dalle sette alle ventuno.","The swimming pool is available from seven a.m. to nine p.m."],["Il corso per principianti è martedì alle diciotto.","The beginners’ class is on Tuesday at six p.m."],["La domenica il centro è chiuso.","The centre is closed on Sundays."],["Per entrare serve la tessera.","You need a membership card to enter."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r09', 'reading', NULL, 8, '{"id":"r09","level":"A1","title":"Avviso alla stazione","theme":"notices","sentences":[["Il treno per Firenze delle dieci è in ritardo.","The ten o’clock train to Florence is delayed."],["Il nuovo orario di partenza è dieci e venticinque.","The new departure time is ten twenty-five."],["Il treno parte dal binario otto.","The train leaves from platform eight."],["I passeggeri devono conservare il biglietto.","Passengers must keep their ticket."],["Ci scusiamo per il disagio.","We apologise for the inconvenience."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r10', 'reading', NULL, 9, '{"id":"r10","level":"A1","title":"Una cartolina da Napoli","theme":"postcard","sentences":[["Cara Anna, sono a Napoli per quattro giorni.","Dear Anna, I’m in Naples for four days."],["Il tempo è caldo e il mare è bellissimo.","The weather is warm and the sea is beautiful."],["Ieri ho visitato il centro storico.","Yesterday I visited the historic centre."],["Ho mangiato una pizza davvero buona.","I ate a really good pizza."],["A presto, un abbraccio da Luca.","See you soon, a hug from Luca."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r11', 'reading', NULL, 10, '{"id":"r11","level":"A1","title":"Menù del giorno","theme":"menu","sentences":[["Il menù del giorno costa quindici euro.","The menu of the day costs fifteen euros."],["Come primo c’è la pasta al pomodoro.","The first course is pasta with tomato sauce."],["Come secondo si può scegliere pollo o pesce.","For the main course you can choose chicken or fish."],["L’acqua è inclusa, ma il caffè è extra.","Water is included, but coffee costs extra."],["Il ristorante accetta carte e contanti.","The restaurant accepts cards and cash."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r12', 'reading', NULL, 11, '{"id":"r12","level":"A1","title":"Annuncio di una casa","theme":"advert","sentences":[["Affittasi appartamento tranquillo vicino al parco.","Quiet flat for rent near the park."],["Ci sono una camera, un soggiorno e un bagno.","There is one bedroom, a living room and a bathroom."],["La cucina è piccola ma moderna.","The kitchen is small but modern."],["L’affitto è ottocento euro al mese.","The rent is eight hundred euros per month."],["Le spese non sono incluse.","Bills are not included."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r13', 'reading', NULL, 12, '{"id":"r13","level":"A1","title":"E-mail all’albergo","theme":"email","sentences":[["Buongiorno, vorrei prenotare una camera singola.","Good morning, I would like to book a single room."],["Arrivo venerdì 12 maggio e parto domenica 14.","I arrive on Friday 12 May and leave on Sunday 14."],["Vorrei sapere se la colazione è inclusa.","I would like to know whether breakfast is included."],["Avete anche un parcheggio privato?","Do you also have a private car park?"],["Grazie per la risposta.","Thank you for your reply."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p13', 'preposition', NULL, 12, '{"id":"p13","before":"Lavoro","target":"ufficio","hint":"in + l’","answer":"nell’","full":"Lavoro nell’ufficio al secondo piano.","beforeEn":"I work in the","targetEn":"office","hintEn":"in + l’ (in + the)","fullEn":"I work in the office on the second floor."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r14', 'reading', NULL, 13, '{"id":"r14","level":"A1","title":"La mia famiglia","theme":"family","sentences":[["Nella mia famiglia siamo in cinque.","There are five people in my family."],["Mio padre lavora in un ufficio e mia madre insegna.","My father works in an office and my mother teaches."],["Ho una sorella maggiore e un fratello piccolo.","I have an older sister and a younger brother."],["La domenica pranziamo spesso dai nonni.","On Sundays we often have lunch at our grandparents’ home."],["Ci piace parlare e giocare insieme.","We like talking and playing together."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p14', 'preposition', NULL, 13, '{"id":"p14","before":"Vado","target":"stazione","hint":"a + la","answer":"alla","full":"Vado alla stazione in autobus.","beforeEn":"I go to the","targetEn":"station","hintEn":"a + la (to + the)","fullEn":"I go to the station by bus."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r15', 'reading', NULL, 14, '{"id":"r15","level":"A1","title":"Dal medico","theme":"health","sentences":[["Da due giorni ho mal di gola e la febbre.","I have had a sore throat and fever for two days."],["Telefono al medico e prenoto una visita.","I phone the doctor and book an appointment."],["Il medico mi fa alcune domande.","The doctor asks me some questions."],["Devo riposare e prendere una medicina dopo i pasti.","I must rest and take medicine after meals."],["Se sto peggio, devo telefonare di nuovo.","If I get worse, I must phone again."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p15', 'preposition', NULL, 14, '{"id":"p15","before":"Usciamo","target":"cinema","hint":"da + il","answer":"dal","full":"Usciamo dal cinema alle undici.","beforeEn":"We leave the","targetEn":"cinema","hintEn":"da + il (from + the)","fullEn":"We leave the cinema at eleven."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r16', 'reading', NULL, 15, '{"id":"r16","level":"A1","title":"Primo giorno di lavoro","theme":"work","sentences":[["Oggi è il mio primo giorno nel nuovo ufficio.","Today is my first day in the new office."],["La mia collega mi mostra la scrivania e la cucina.","My colleague shows me the desk and the kitchen."],["Alle dieci abbiamo una breve riunione.","At ten we have a short meeting."],["La pausa pranzo inizia alle tredici.","The lunch break starts at one p.m."],["Finisco il lavoro alle cinque e mezza.","I finish work at half past five."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p16', 'preposition', NULL, 15, '{"id":"p16","before":"La porta","target":"camera","hint":"di + la","answer":"della","full":"La porta della camera è chiusa.","beforeEn":"The door of the","targetEn":"room","hintEn":"di + la (of + the)","fullEn":"The room door is closed."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r17', 'reading', NULL, 16, '{"id":"r17","level":"A1","title":"Una giornata di pioggia","theme":"weather","sentences":[["Stamattina il cielo è grigio e piove forte.","This morning the sky is grey and it is raining heavily."],["Prendo l’ombrello e indosso il cappotto.","I take my umbrella and put on my coat."],["L’autobus arriva con dieci minuti di ritardo.","The bus arrives ten minutes late."],["Nel pomeriggio il vento diventa più forte.","In the afternoon the wind becomes stronger."],["Domani invece è previsto il sole.","Tomorrow, however, sunshine is forecast."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p17', 'preposition', NULL, 16, '{"id":"p17","before":"Il gatto è","target":"divano","hint":"su + il","answer":"sul","full":"Il gatto è sul divano.","beforeEn":"The cat is on the","targetEn":"sofa","hintEn":"su + il (on + the)","fullEn":"The cat is on the sofa."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r18', 'reading', NULL, 17, '{"id":"r18","level":"A1","title":"Fare la spesa","theme":"shopping","sentences":[["Entro al supermercato con una lista corta.","I enter the supermarket with a short list."],["Compro del pane, un litro di latte e sei uova.","I buy some bread, a litre of milk and six eggs."],["La frutta è vicino all’ingresso.","The fruit is near the entrance."],["Alla cassa pago con la carta.","At the checkout I pay by card."],["Controllo lo scontrino prima di uscire.","I check the receipt before leaving."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p18', 'preposition', NULL, 17, '{"id":"p18","before":"Mangiamo","target":"ristorante","hint":"in + il","answer":"nel","full":"Mangiamo nel ristorante dell’albergo.","beforeEn":"We eat in the","targetEn":"restaurant","hintEn":"in + il (in + the)","fullEn":"We eat in the hotel restaurant."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r19', 'reading', NULL, 18, '{"id":"r19","level":"A1","title":"Indicazioni per il museo","theme":"directions","sentences":[["Esci dalla stazione e gira a sinistra.","Leave the station and turn left."],["Continua sempre dritto fino al semaforo.","Continue straight ahead to the traffic light."],["Attraversa la strada e passa davanti alla banca.","Cross the road and go past the bank."],["Il museo è accanto alla biblioteca.","The museum is next to the library."],["A piedi ci vogliono circa dieci minuti.","It takes about ten minutes on foot."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p19', 'preposition', NULL, 18, '{"id":"p19","before":"Andiamo","target":"spiaggia","hint":"a + la","answer":"alla","full":"Andiamo alla spiaggia a piedi.","beforeEn":"We go to the","targetEn":"beach","hintEn":"a + la (to + the)","fullEn":"We walk to the beach."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('reading:r20', 'reading', NULL, 19, '{"id":"r20","level":"A1","title":"Programma del fine settimana","theme":"plans","sentences":[["Sabato mattina devo fare la spesa e pulire casa.","On Saturday morning I must shop and clean the house."],["Nel pomeriggio incontro due amici al parco.","In the afternoon I meet two friends at the park."],["Se fa bel tempo, facciamo una passeggiata.","If the weather is good, we go for a walk."],["Domenica vorrei dormire fino a tardi.","On Sunday I would like to sleep late."],["La sera preparo la settimana nuova.","In the evening I prepare for the new week."]]}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p20', 'preposition', NULL, 19, '{"id":"p20","before":"Il bar è","target":"angolo","hint":"a + l’","answer":"all’","full":"Il bar è all’angolo.","beforeEn":"The café is on the","targetEn":"corner","hintEn":"a + l’ (at + the)","fullEn":"The café is on the corner."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p21', 'preposition', NULL, 20, '{"id":"p21","before":"Torno","target":"lavoro","hint":"da + il","answer":"dal","full":"Torno dal lavoro alle sei.","beforeEn":"I return from","targetEn":"work","hintEn":"da + il (from + the)","fullEn":"I return from work at six."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p22', 'preposition', NULL, 21, '{"id":"p22","before":"Il prezzo","target":"biglietti","hint":"di + i","answer":"dei","full":"Il prezzo dei biglietti è alto.","beforeEn":"The price of the","targetEn":"tickets","hintEn":"di + i (of + the)","fullEn":"The ticket price is high."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p23', 'preposition', NULL, 22, '{"id":"p23","before":"Siamo","target":"supermercato","hint":"in + il","answer":"nel","full":"Siamo nel supermercato.","beforeEn":"We are in the","targetEn":"supermarket","hintEn":"in + il (in + the)","fullEn":"We are in the supermarket."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p24', 'preposition', NULL, 23, '{"id":"p24","before":"Metto i libri","target":"scaffale","hint":"su + lo","answer":"sullo","full":"Metto i libri sullo scaffale.","beforeEn":"I put the books on the","targetEn":"shelf","hintEn":"su + lo (on + the)","fullEn":"I put the books on the shelf."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p25', 'preposition', NULL, 24, '{"id":"p25","before":"Telefono","target":"amica","hint":"a + l’","answer":"all’","full":"Telefono all’amica di Marta.","beforeEn":"I phone Marta’s","targetEn":"friend","hintEn":"a + l’ (to + the)","fullEn":"I phone Marta’s friend."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p26', 'preposition', NULL, 25, '{"id":"p26","before":"Veniamo","target":"aeroporto","hint":"da + l’","answer":"dall’","full":"Veniamo dall’aeroporto in taxi.","beforeEn":"We come from the","targetEn":"airport","hintEn":"da + l’ (from + the)","fullEn":"We come from the airport by taxi."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p27', 'preposition', NULL, 26, '{"id":"p27","before":"La finestra","target":"studio","hint":"di + lo","answer":"dello","full":"La finestra dello studio è aperta.","beforeEn":"The window of the","targetEn":"study","hintEn":"di + lo (of + the)","fullEn":"The study window is open."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p28', 'preposition', NULL, 27, '{"id":"p28","before":"Dormiamo","target":"albergo","hint":"in + l’","answer":"nell’","full":"Dormiamo nell’albergo vicino al mare.","beforeEn":"We sleep in the","targetEn":"hotel","hintEn":"in + l’ (in + the)","fullEn":"We sleep in the hotel near the sea."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p29', 'preposition', NULL, 28, '{"id":"p29","before":"Il quadro è","target":"pareti","hint":"su + le","answer":"sulle","full":"Il quadro è sulle pareti del corridoio.","beforeEn":"The picture is on the","targetEn":"walls","hintEn":"su + le (on + the)","fullEn":"The picture is on the hallway walls."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p30', 'preposition', NULL, 29, '{"id":"p30","before":"Andiamo","target":"isole","hint":"a + le","answer":"alle","full":"Andiamo alle isole in estate.","beforeEn":"We go to the","targetEn":"islands","hintEn":"a + le (to + the)","fullEn":"We go to the islands in summer."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p31', 'preposition', NULL, 30, '{"id":"p31","before":"Partiamo","target":"montagne","hint":"da + le","answer":"dalle","full":"Partiamo dalle montagne domenica.","beforeEn":"We leave the","targetEn":"mountains","hintEn":"da + le (from + the)","fullEn":"We leave the mountains on Sunday."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p32', 'preposition', NULL, 31, '{"id":"p32","before":"Parliamo","target":"esami","hint":"di + gli","answer":"degli","full":"Parliamo degli esami di giugno.","beforeEn":"We talk about the","targetEn":"exams","hintEn":"di + gli (about + the)","fullEn":"We talk about the June exams."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p33', 'preposition', NULL, 32, '{"id":"p33","before":"Abito","target":"Stati Uniti","hint":"in","answer":"negli","full":"Abito negli Stati Uniti.","beforeEn":"I live in the","targetEn":"United States","hintEn":"in + gli (in + the)","fullEn":"I live in the United States."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p34', 'preposition', NULL, 33, '{"id":"p34","before":"Vado","target":"Paesi Bassi","hint":"in","answer":"nei","full":"Vado nei Paesi Bassi per lavoro.","beforeEn":"I go to the","targetEn":"Netherlands","hintEn":"in + i (to + the)","fullEn":"I go to the Netherlands for work."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p35', 'preposition', NULL, 34, '{"id":"p35","before":"Il regalo è","target":"bambini","hint":"per + i","answer":"per i","full":"Il regalo è per i bambini.","beforeEn":"The gift is for the","targetEn":"children","hintEn":"per + i (for the)","fullEn":"The gift is for the children."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p36', 'preposition', NULL, 35, '{"id":"p36","before":"Cammino","target":"parco","hint":"attraverso il","answer":"attraverso il","full":"Cammino attraverso il parco.","beforeEn":"I walk through the","targetEn":"park","hintEn":"attraverso + il (through the)","fullEn":"I walk through the park."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p37', 'preposition', NULL, 36, '{"id":"p37","before":"La farmacia è","target":"banca","hint":"vicino a + la","answer":"vicino alla","full":"La farmacia è vicino alla banca.","beforeEn":"The pharmacy is near the","targetEn":"bank","hintEn":"vicino a + la (near the)","fullEn":"The pharmacy is near the bank."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p38', 'preposition', NULL, 37, '{"id":"p38","before":"La fermata è","target":"museo","hint":"davanti a + il","answer":"davanti al","full":"La fermata è davanti al museo.","beforeEn":"The stop is in front of the","targetEn":"museum","hintEn":"davanti a + il (in front of the)","fullEn":"The stop is in front of the museum."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p39', 'preposition', NULL, 38, '{"id":"p39","before":"Il ristorante è","target":"teatro","hint":"accanto a + il","answer":"accanto al","full":"Il ristorante è accanto al teatro.","beforeEn":"The restaurant is next to the","targetEn":"theatre","hintEn":"accanto a + il (next to the)","fullEn":"The restaurant is next to the theatre."}');
INSERT OR REPLACE INTO content_items (id, kind, lesson_id, position, payload) VALUES ('preposition:p40', 'preposition', NULL, 39, '{"id":"p40","before":"Aspetto","target":"stazione","hint":"fuori da + la","answer":"fuori dalla","full":"Aspetto fuori dalla stazione.","beforeEn":"I wait outside the","targetEn":"station","hintEn":"fuori da + la (outside the)","fullEn":"I wait outside the station."}');
